import type { BankQuestion } from "@/lib/bank";

/** Limits, Continuity and Differentiability (Mathematics (JEE)): 129 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"math-limits-continuity-1","question":"lim (x → 0) sin 3x / x equals:","options":["3","1","0","1/3"],"answer":0,"explanation":"Write sin 3x / x = 3 · (sin 3x / 3x). As x → 0, sin 3x / 3x → 1, so the limit is 3. Forgetting the factor 3 gives the wrong answer 1.","difficulty":"easy","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-2","question":"lim (x → ∞) (3x² + 2x + 1)/(x² + 5) equals:","options":["0","1/5","∞","3"],"answer":3,"explanation":"Divide numerator and denominator by x²: (3 + 2/x + 1/x²)/(1 + 5/x²) → 3/1 = 3 as x → ∞. Equal degrees give the ratio of leading coefficients.","difficulty":"easy","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-3","question":"The function f(x) = |x| is continuous everywhere but fails to be differentiable at:","options":["x = 1","no point; it is differentiable everywhere","x = 0","every integer"],"answer":2,"explanation":"At x = 0 the left-hand derivative is −1 and the right-hand derivative is +1, so f'(0) does not exist. Elsewhere |x| equals x or −x, which are differentiable.","difficulty":"easy"},
  {"id":"math-limits-continuity-4","question":"lim (x → 0) (1 − cos x)/x² equals:","options":["0","1/2","1","2"],"answer":1,"explanation":"1 − cos x = 2 sin²(x/2), so the expression is 2 sin²(x/2)/x² = (1/2)·(sin(x/2)/(x/2))² → 1/2. Replacing 1 − cos x by x² (instead of x²/2) is the common slip that gives 1.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-5","question":"lim (x → ∞) (1 + 2/x)^x equals:","options":["e","e²","1","2e"],"answer":1,"explanation":"Put x = 2t: (1 + 1/t)^(2t) = [(1 + 1/t)^t]² → e². In general (1 + a/x)^x → e^a.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-6","question":"f(x) = (x² − 9)/(x − 3) for x ≠ 3 and f(3) = k. The value of k for which f is continuous at x = 3 is:","options":["6","9","3","0"],"answer":0,"explanation":"For x ≠ 3, f(x) = (x − 3)(x + 3)/(x − 3) = x + 3, so lim (x → 3) f(x) = 6. Continuity needs f(3) = 6, hence k = 6.","difficulty":"moderate"},
  {"id":"math-limits-continuity-7","question":"lim (x → 2) (x³ − 8)/(x² − 4) equals:","options":["4","6","2","3"],"answer":3,"explanation":"Factor: (x − 2)(x² + 2x + 4)/((x − 2)(x + 2)) = (x² + 2x + 4)/(x + 2) → (4 + 4 + 4)/4 = 12/4 = 3. L'Hôpital gives the same: 3x²/2x = 3·4/4 = 3.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-8","question":"lim (x → 0) (e^x − 1)/sin x equals:","options":["e","∞","1","0"],"answer":2,"explanation":"Write it as [(e^x − 1)/x] ÷ [sin x / x]. Both brackets tend to 1, so the limit is 1/1 = 1.","difficulty":"moderate"},
  {"id":"math-limits-continuity-9","question":"The domain of f(x) = √(x − 1) + 1/(x − 3) is:","options":["[1, ∞)","(1, ∞)","[1, 3) ∪ (3, ∞)","(3, ∞)"],"answer":2,"explanation":"√(x − 1) needs x ≥ 1 and 1/(x − 3) needs x ≠ 3. Together: [1, 3) ∪ (3, ∞). Option [1, ∞) wrongly keeps x = 3, where the function is undefined.","difficulty":"moderate"},
  {"id":"math-limits-continuity-10","question":"lim (x → 0) (tan x − sin x)/x³ equals:","options":["0","1/2","1","1/6"],"answer":1,"explanation":"tan x − sin x = tan x (1 − cos x) ≈ x · (x²/2) = x³/2 for small x, so the ratio → 1/2. Using series: tan x = x + x³/3 + …, sin x = x − x³/6 + …, difference = x³(1/3 + 1/6) = x³/2.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-11","question":"lim (x → 0) (cos x)^(1/x²) equals:","options":["e^(−1/2)","e^(1/2)","1","e^(−1)"],"answer":0,"explanation":"Let L be the limit. ln L = lim ln(cos x)/x² = lim ln(1 − 2sin²(x/2))/x² ≈ lim (−x²/2)/x² = −1/2. So L = e^(−1/2). The 1^∞ form must be handled with logs; answering 1 is the standard trap.","difficulty":"hard","source":"JEE Main 2022 pattern"},
  {"id":"math-limits-continuity-12","question":"Let f(x) = x² sin(1/x) for x ≠ 0 and f(0) = 0. Which statement is correct?","options":["f is not continuous at x = 0","f is continuous but not differentiable at x = 0","f is differentiable at x = 0 and f' is continuous at x = 0","f is differentiable at x = 0 but f' is not continuous at x = 0"],"answer":3,"explanation":"f'(0) = lim h² sin(1/h)/h = lim h sin(1/h) = 0 (squeeze), so f is differentiable at 0. For x ≠ 0, f'(x) = 2x sin(1/x) − cos(1/x), and cos(1/x) has no limit as x → 0, so f' is discontinuous at 0.","difficulty":"hard","source":"JEE Advanced pattern"},
  {"id":"math-limits-continuity-13","question":"lim (x → ∞) (√(x² + 4x) − x) equals:","options":["1","4","0","2"],"answer":3,"explanation":"Rationalise: (x² + 4x − x²)/(√(x² + 4x) + x) = 4x/(x√(1 + 4/x) + x) → 4/(1 + 1) = 2. Treating ∞ − ∞ as 0 is the trap.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-14","question":"Let [x] denote the greatest integer ≤ x. The number of points in (0, 3) at which f(x) = [x] sin(πx) is NOT differentiable is:","options":["0","1","2","3"],"answer":2,"explanation":"f is continuous at x = 1 and x = 2 because sin(πx) = 0 there. At x = 1: left derivative 0 (f = 0 on (0,1)), right derivative π cos π = −π, so not differentiable. At x = 2: left derivative π cos 2π = π, right derivative 2π cos 2π = 2π, not differentiable. So exactly 2 points.","difficulty":"hard","source":"JEE Main 2023 pattern"},
  {"id":"math-limits-continuity-15","question":"lim (x → 0) (x − tan⁻¹x)/(x − sin x) equals:","options":["3","2","1","1/2"],"answer":1,"explanation":"tan⁻¹x = x − x³/3 + …, so x − tan⁻¹x ≈ x³/3; sin x = x − x³/6 + …, so x − sin x ≈ x³/6. Ratio = (1/3)/(1/6) = 2.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-16","question":"If lim (x → 0) (sin 2x + a sin x)/x³ exists and is finite, then a and the value of the limit are respectively:","options":["a = −2, limit = −1","a = 2, limit = 1","a = −2, limit = 1","a = −1, limit = −1"],"answer":0,"explanation":"Expand: sin 2x + a sin x = (2 + a)x + (−8/6 − a/6)x³ + …. For a finite limit the x term must vanish, so a = −2. Then the x³ coefficient is −4/3 + 2/6 = −1, giving limit −1.","difficulty":"hard","source":"JEE Main 2021 pattern"},
  {"id":"math-limits-continuity-17","question":"For f(x) = x|x|, which statement is correct at x = 0?","options":["f is differentiable at 0, f' is continuous at 0, but f''(0) does not exist","f is differentiable at 0 but f' is not continuous at 0","f is not differentiable at 0","f is twice differentiable at 0"],"answer":0,"explanation":"f(x) = x² for x ≥ 0 and −x² for x < 0, so f'(x) = 2|x|, which is continuous with f'(0) = 0. But f' = 2|x| has a corner at 0, so f''(0) does not exist.","difficulty":"hard","source":"JEE Advanced pattern"},
  {"id":"math-limits-continuity-18","question":"lim (x → 0) (1 + tan x)^(1/sin 2x) equals:","options":["1","e","e²","√e"],"answer":3,"explanation":"1^∞ form: limit = e^(lim tan x / sin 2x) = e^(lim (x/2x)) = e^(1/2) = √e.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-19","question":"Let f(x) = [x], the greatest integer function. How many of the following statements are correct?\n(1) f is continuous at every non-integer.\n(2) f is right-continuous at every integer.\n(3) f is differentiable at every non-integer with f'(x) = 0.\n(4) lim (x → 2⁻) f(x) = 2.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(1), (2), (3) are true: [x] is constant on each (n, n+1) and equals n at n⁺. (4) is false: just left of 2, [x] = 1, so the left limit is 1. Three statements are correct.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-20","question":"lim (x → 0) ((2^x + 8^x)/2)^(1/x) equals:","options":["2","8","4","16"],"answer":2,"explanation":"Let L be the limit. ln L = lim ln((2^x + 8^x)/2)/x; by L'Hôpital this is lim (2^x ln 2 + 8^x ln 8)/(2^x + 8^x) = (ln 2 + ln 8)/2 = ln 16 / 2 = ln 4. So L = 4 (the geometric mean √(2·8)).","difficulty":"very-hard","source":"JEE Main 2022 pattern"},
  {"id":"math-limits-continuity-21","question":"lim (n → ∞) Σ (k = 1 to n) k/(n² + k) equals:","options":["1","1/2","2","0"],"answer":1,"explanation":"Squeeze: Σk/(n² + n) ≤ S ≤ Σk/(n² + 1), and Σk = n(n + 1)/2. Both bounds equal n(n+1)/2 divided by something ≈ n², so both → 1/2. Hence the limit is 1/2.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-limits-continuity-22","question":"For f(x) = |x − 1| + |x + 1| + |x|, which is correct?","options":["Non-differentiable at exactly 2 points; minimum value 2","Non-differentiable at exactly 3 points; minimum value 2","Non-differentiable at exactly 3 points; minimum value 1","Non-differentiable at exactly 2 points; minimum value 1"],"answer":1,"explanation":"Corners occur where each modulus vanishes: x = −1, 0, 1 (three points). f is piecewise linear with slope −3 for x < −1, −1 on (−1,0), +1 on (0,1), +3 for x > 1, so the minimum is at x = 0: f(0) = 1 + 1 + 0 = 2.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-23","question":"lim (x → π/4) (1 − tan x)/(1 − √2 sin x) equals:","options":["2","1/2","√2","1"],"answer":0,"explanation":"0/0 form, so use L'Hôpital: numerator derivative −sec²x → −2 at π/4; denominator derivative −√2 cos x → −√2·(1/√2) = −1. Limit = (−2)/(−1) = 2.","difficulty":"very-hard","source":"JEE Main 2021 pattern"},
  {"id":"math-limits-continuity-24","question":"Assertion (A): f(x) = |sin x| is not differentiable at x = nπ, n an integer.\nReason (R): |g(x)| is non-differentiable at every point where g(x) = 0.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true: at x = nπ, sin x changes sign with non-zero slope, so |sin x| has a corner. R is false as a general rule: g(x) = x² gives |g| = x², which is differentiable at 0 where g = 0. The modulus creates a corner only when g crosses zero with g' ≠ 0.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-limits-continuity-25","question":"The domain of f(x) = ln(1 − ln(x² − 5x + 16)) is:","options":["R","(1, 4)","(2, 3)","the empty set"],"answer":3,"explanation":"x² − 5x + 16 has minimum 16 − 25/4 = 9.75 > 0, so the inner log exists for all x. But we also need 1 − ln(x² − 5x + 16) > 0, i.e. x² − 5x + 16 < e ≈ 2.72, impossible since the expression is always ≥ 9.75. The domain is empty.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-26","question":"f(x) = x² + 3x + a for x ≤ 1 and f(x) = bx + 2 for x > 1 is differentiable for all real x. Then (a, b) equals:","options":["(2, 5)","(5, 3)","(3, 5)","(3, 2)"],"answer":2,"explanation":"Differentiability at x = 1 needs matching derivatives: 2(1) + 3 = b, so b = 5. Continuity at x = 1: 1 + 3 + a = b + 2 = 7, so a = 3.","difficulty":"very-hard","source":"JEE Main 2020 pattern"},
  {"id":"math-limits-continuity-27","question":"lim (x → 0) (e^(x²) − cos x)/(x sin x) equals:","options":["1/2","1","3/2","2"],"answer":2,"explanation":"e^(x²) = 1 + x² + …, cos x = 1 − x²/2 + …, so the numerator ≈ 3x²/2. The denominator x sin x ≈ x². Limit = 3/2.","difficulty":"very-hard","source":"JEE Main 2023 pattern"},
  {"id":"math-limits-continuity-28","question":"How many of the following statements are correct?\n(1) If f and g are both discontinuous at a, then f + g must be discontinuous at a.\n(2) If f is continuous at a and g is discontinuous at a, then f + g is discontinuous at a.\n(3) If f·g is continuous at a, then both f and g must be continuous at a.\n(4) If f is differentiable at a, then f is continuous at a.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"(2) and (4) are true. (1) is false: f = [x] and g = −[x] are discontinuous at integers but their sum 0 is continuous. (3) is false: f = [x] and g = 0 give a continuous product. Two statements are correct.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-29","question":"Let [·] denote the greatest integer function. lim (x → 0) ([sin x / x] + [tan x / x]) equals:","options":["0","1","2","does not exist"],"answer":1,"explanation":"For small x ≠ 0, sin x / x is slightly less than 1, so [sin x / x] = 0, while tan x / x is slightly greater than 1, so [tan x / x] = 1. The sum is 0 + 1 = 1 on both sides of 0, so the limit is 1. Answering 2 (treating both as 1) is the trap.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-limits-continuity-30","question":"f(x) = (1 − cos 2x)/x² for x < 0, f(0) = k, and f(x) = √x/(√(16 + √x) − 4) for x > 0. The value of k that makes f continuous at x = 0 is:","options":["No such k exists","8","4","2"],"answer":0,"explanation":"Left limit: (1 − cos 2x)/x² = 2 sin²x/x² → 2. Right limit: multiply by the conjugate: √x(√(16 + √x) + 4)/√x = √(16 + √x) + 4 → 8. The one-sided limits differ (2 ≠ 8), so no value of k makes f continuous at 0.","difficulty":"very-hard","source":"JEE Main 2022 pattern"},
  {"id": "math-limits-continuity-31", "question": "lim (x → 0) tan 5x/sin 2x equals:", "options": ["5/2", "2/5", "1", "10"], "answer": 0, "explanation": "tan 5x ≈ 5x and sin 2x ≈ 2x near 0, so the limit is 5/2.", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-32", "question": "lim (x → 0) (5ˣ − 3ˣ)/x equals:", "options": ["ln 15", "2", "ln 2", "ln(5/3)"], "answer": 3, "explanation": "(aˣ − 1)/x → ln a, so the limit is ln 5 − ln 3 = ln(5/3).", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-33", "question": "lim (x → ∞) x sin(1/x) equals:", "options": ["0", "∞", "1", "does not exist"], "answer": 2, "explanation": "Put t = 1/x → 0⁺: the expression becomes (sin t)/t → 1. The answer 0 confuses this with x → 0.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-34", "question": "The number of points at which f(x) = |x − 2| + |x + 3| is not differentiable is:", "options": ["2", "1", "3", "0"], "answer": 0, "explanation": "Each term has a corner where its argument changes sign, at x = 2 and x = −3. The slopes there are not cancelled (they jump from −2 to 0 at x = −3 and from 0 to 2 at x = 2), so there are 2 points.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-35", "question": "lim (x → 0) (1 − cos x·√(cos 2x))/x² equals:", "options": ["1/2", "1", "2", "3/2"], "answer": 3, "explanation": "cos x ≈ 1 − x²/2 and √(cos 2x) ≈ 1 − x², so the product is ≈ 1 − 3x²/2. The limit is 3/2.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-36", "question": "lim (x → 0) sin(π cos²x)/x² equals:", "options": ["−π", "π", "π/2", "1"], "answer": 1, "explanation": "sin(π cos²x) = sin(π − π sin²x) = sin(π sin²x) ≈ π sin²x ≈ πx². The limit is π.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-37", "question": "With [·] the greatest integer function, lim (x → 0) x[1/x] equals:", "options": ["0", "1", "does not exist", "∞"], "answer": 1, "explanation": "x[1/x] = x(1/x − {1/x}) = 1 − x{1/x}. Since 0 ≤ {1/x} < 1, x{1/x} → 0 from either side, so the limit is 1.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-38", "question": "f(x) = [ln(1 + 3x) − ln(1 − 2x)]/x for x ≠ 0 is continuous at x = 0. Then f(0) equals:", "options": ["1", "6", "−1", "5"], "answer": 3, "explanation": "ln(1 + 3x)/x → 3 and ln(1 − 2x)/x → −2, so f(0) = 3 − (−2) = 5.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-39", "question": "lim (x → 0) ((1 + x)^(1/x) − e)/x equals:", "options": ["−e/2", "e/2", "e", "0"], "answer": 0, "explanation": "(1 + x)^(1/x) = e^(ln(1 + x)/x) = e^(1 − x/2 + …) = e(1 − x/2 + …). So the numerator is ≈ −ex/2 and the limit is −e/2.", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id": "math-limits-continuity-40", "question": "lim (x → 0) (sin x/x)^(1/x²) equals:", "options": ["e^(1/6)", "1", "e^(−1/6)", "e^(−1/3)"], "answer": 2, "explanation": "This is a 1^∞ form: the limit is e^L with L = lim (sin x/x − 1)/x² = lim (−x²/6)/x² = −1/6.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-41", "question": "Consider (with [·] the greatest integer function):\n(1) f(x) = [x] + [−x] is continuous at every non-integer x.\n(2) f(x) = x[x] is continuous at x = 0.\n(3) f(x) = |x|³ is differentiable at x = 0.\n(4) f(x) = x·sgn(x) is differentiable at x = 0.\nHow many of these statements are correct?", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(1) True: the sum is −1 on every open interval between integers. (2) True: x[x] → 0 from both sides and equals 0 at 0. (3) True: the derivative there is 0. (4) False: x·sgn(x) = |x|, which has a corner at 0. Three are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-42", "question": "With [·] the greatest integer function, the number of points in (−2, 2) at which f(x) = [x²] is discontinuous is:", "options": ["3", "6", "7", "4"], "answer": 1, "explanation": "[x²] jumps where x² crosses an integer. On (−2, 2), x² ∈ [0, 4), so the jumps are at x² = 1, 2, 3, i.e. x = ±1, ±√2, ±√3. At x = 0, x² stays in [0, 1), so f is continuous there. Total 6.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-43", "question": "lim (x → 0) (cos(sin x) − cos x)/x⁴ equals:", "options": ["1/12", "1/24", "1/6", "1/3"], "answer": 2, "explanation": "sin²x = x² − x⁴/3 + …, so cos(sin x) = 1 − sin²x/2 + sin⁴x/24 = 1 − x²/2 + x⁴/6 + x⁴/24 + … = 1 − x²/2 + 5x⁴/24. Also cos x = 1 − x²/2 + x⁴/24. The difference is 4x⁴/24 = x⁴/6, so the limit is 1/6.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-limits-continuity-44", "question": "f(x) = ax² + b for x < 1 and f(x) = 1/|x| for x ≥ 1 is differentiable at x = 1. Then (a, b) equals:", "options": ["(−1/2, 3/2)", "(1/2, 1/2)", "(−1/2, 1/2)", "(1, 0)"], "answer": 0, "explanation": "Continuity: a + b = 1. Near x = 1 the right part is 1/x, with derivative −1 there; the left derivative is 2a. So 2a = −1, a = −1/2 and b = 3/2.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-45", "question": "lim (n → ∞) (n!/nⁿ)^(1/n) equals:", "options": ["e", "1/e", "1", "0"], "answer": 1, "explanation": "ln of the expression = (1/n) Σ ln(r/n) → ∫₀¹ ln x dx = −1, so the limit is e⁻¹. The answer 0 wrongly assumes n!/nⁿ → 0 forces the root to 0.", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id": "math-limits-continuity-46", "question": "lim (x → 0) ln(1 + 4x)/x equals:", "options": ["1", "1/4", "4", "0"], "answer": 2, "explanation": "ln(1 + 4x)/x = 4·[ln(1 + 4x)/(4x)] and ln(1 + u)/u → 1 as u → 0, so the limit is 4.", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-47", "question": "If x is measured in degrees, lim (x → 0) (sin x)/x equals:", "options": ["π/180", "1", "180/π", "0"], "answer": 0, "explanation": "x degrees = πx/180 radians, so sin x° / x = [sin(πx/180)/(πx/180)]·(π/180) → π/180. The standard limit 1 holds only for radians.", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-48", "question": "lim (x → 1) (x¹⁰ − 1)/(x⁵ − 1) equals:", "options": ["1/2", "5", "10", "2"], "answer": 3, "explanation": "x¹⁰ − 1 = (x⁵ − 1)(x⁵ + 1), so the expression is x⁵ + 1 → 2. (Equivalently 10/5 by the formula lim (xⁿ − 1)/(x − 1) = n.)", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-49", "question": "lim (x → 0) [√(1 + x) − √(1 − x)]/x equals:", "options": ["2", "1", "1/2", "0"], "answer": 1, "explanation": "Rationalise: [(1 + x) − (1 − x)]/[x(√(1 + x) + √(1 − x))] = 2/(√(1 + x) + √(1 − x)) → 2/2 = 1.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-50", "question": "The left-hand limit lim (x → 0⁻) 1/(1 + e^(1/x)) equals:", "options": ["0", "1", "1/2", "does not exist"], "answer": 1, "explanation": "As x → 0⁻, 1/x → −∞, so e^(1/x) → 0 and the expression → 1. From the right e^(1/x) → ∞ and the limit is 0, so the two-sided limit does not exist, but the left-hand limit is 1.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-51", "question": "lim (x → ∞) ((x + 3)/(x − 1))ˣ equals:", "options": ["e³", "e²", "1", "e⁴"], "answer": 3, "explanation": "This is a 1^∞ form: the limit is e^L with L = lim x[(x + 3)/(x − 1) − 1] = lim 4x/(x − 1) = 4. So the answer is e⁴.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-52", "question": "f(x) = (e^(3x) − 1)/ln(1 + 2x) for x ≠ 0 is continuous at x = 0. Then f(0) equals:", "options": ["3/2", "2/3", "3", "1"], "answer": 0, "explanation": "f(x) = [(e^(3x) − 1)/(3x)]·[2x/ln(1 + 2x)]·(3/2) → 1·1·3/2 = 3/2.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-53", "question": "lim (n → ∞) n(2^(1/n) − 1) equals:", "options": ["1", "2", "ln 2", "0"], "answer": 2, "explanation": "Put h = 1/n → 0: the limit becomes (2ʰ − 1)/h → ln 2, using lim (aʰ − 1)/h = ln a.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-54", "question": "lim (x → 0) (1 − cos 2x)(3 + cos x)/(x tan 4x) equals:", "options": ["1", "4", "1/2", "2"], "answer": 3, "explanation": "1 − cos 2x = 2 sin²x ≈ 2x², 3 + cos x → 4 and x tan 4x ≈ 4x². The limit is (2x² · 4)/(4x²) = 2.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-55", "question": "lim (x → 1) (1 − x) tan(πx/2) equals:", "options": ["π/2", "2/π", "0", "1"], "answer": 1, "explanation": "Put x = 1 − h: tan(π/2 − πh/2) = cot(πh/2), so the expression is h·cot(πh/2) = h/tan(πh/2) → 2/π.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-56", "question": "lim (x → 0) sin(x²)/ln(cos(2x² − x)) equals:", "options": ["2", "−1/2", "−2", "−4"], "answer": 2, "explanation": "Let u = 2x² − x ≈ −x. Then ln(cos u) ≈ −u²/2 ≈ −x²/2, and sin(x²) ≈ x². The limit is x²/(−x²/2) = −2.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-57", "question": "With [·] the greatest integer function, lim (x → 0⁻) sin[x]/[x] equals:", "options": ["sin 1", "1", "0", "does not exist"], "answer": 0, "explanation": "For −1 ≤ x < 0, [x] = −1, so sin[x]/[x] = sin(−1)/(−1) = sin 1, a constant. Using the standard limit sin t/t → 1 is wrong because [x] does not tend to 0. (From the right [x] = 0 and the expression is undefined.)", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-58", "question": "lim (x → 0) (eˣ − 1 − x − x²/2)/x³ equals:", "options": ["1/6", "1/2", "1/3", "0"], "answer": 0, "explanation": "eˣ = 1 + x + x²/2 + x³/6 + …, so the numerator is x³/6 + higher terms and the limit is 1/6.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-59", "question": "lim (n → ∞) (1 + 1/n²)ⁿ equals:", "options": ["e", "e²", "1", "∞"], "answer": 2, "explanation": "It is a 1^∞ form with exponent limit n·(1/n²) = 1/n → 0, so the limit is e⁰ = 1. Answering e confuses it with (1 + 1/n)ⁿ.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-60", "question": "lim (x → 0) (x tan 2x − 2x tan x)/(1 − cos 2x)² equals:", "options": ["2", "1/2", "1/4", "0"], "answer": 1, "explanation": "tan u = u + u³/3 + …, so x tan 2x = 2x² + 8x⁴/3 + … and 2x tan x = 2x² + 2x⁴/3 + …; the numerator is 2x⁴ + …. The denominator is (2 sin²x)² ≈ 4x⁴. The limit is 2/4 = 1/2.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-limits-continuity-61", "question": "Which of the following functions is differentiable at x = 0?", "options": ["|x| + |sin x|", "|x| + sin x", "x + |sin x|", "|x| − |sin x|"], "answer": 3, "explanation": "Near 0, |x| − |sin x| = sgn(x)(x − sin x), and [f(h) − f(0)]/h = (|h| − |sin h|)/h → 0 from both sides. The others have corners: |x| + |sin x| ≈ 2|x| (one-sided derivatives ±2), |x| + sin x (2 and 0), x + |sin x| (2 and 0).", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-limits-continuity-62", "question": "Let f(x) = 1/(1 − x). The set of points where the composite function f(f(f(x))) is discontinuous is:", "options": ["{1}", "{0}", "{0, 1}", "{0, 1, 2}"], "answer": 2, "explanation": "f is undefined at x = 1. f(f(x)) = (x − 1)/x is undefined also at x = 0 (where f(x) = 1). f(f(f(x))) simplifies to x, but the composite is still undefined, hence discontinuous, at x = 0 and x = 1.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-limits-continuity-63", "question": "f is differentiable on R, f(x + y) = f(x)·f(y) for all x, y, f(0) ≠ 0 and f′(0) = 2. Then f′(x) equals:", "options": ["2", "f(x)", "2x·f(x)", "2f(x)"], "answer": 3, "explanation": "Putting x = y = 0 gives f(0) = f(0)², so f(0) = 1. Then f′(x) = lim [f(x)f(h) − f(x)]/h = f(x)·lim [f(h) − 1]/h = f(x)f′(0) = 2f(x) (so f(x) = e^(2x)).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-64", "question": "The number of points in the open interval (0, 2π) at which f(x) = max(sin x, cos x) is not differentiable is:", "options": ["2", "1", "3", "4"], "answer": 0, "explanation": "sin x and cos x are equal at x = π/4 and 5π/4 in (0, 2π). At each, f switches from one curve to the other with different slopes (cos x ≠ −sin x there), giving a corner. Elsewhere f equals one smooth function, so there are 2 such points.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-65", "question": "The number of points at which f(x) = min(1, x², x³) is not differentiable is:", "options": ["0", "1", "2", "3"], "answer": 1, "explanation": "For x ≤ 0, x³ ≤ 0 is the smallest. For 0 ≤ x ≤ 1, x³ ≤ x² ≤ 1. For x > 1 the minimum is 1. So f(x) = x³ for x ≤ 1 and 1 for x > 1: the only corner is x = 1 (left derivative 3, right derivative 0). At x = 0 it is smoothly x³.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-66", "question": "If L = lim (x → 0) [a − √(a² − x²) − x²/4]/x⁴ (a > 0) is finite, then:", "options": ["a = 2 and L = 1/32", "a = 4 and L = 1/64", "a = 1 and L = 1/8", "a = 2 and L = 1/64"], "answer": 3, "explanation": "√(a² − x²) = a − x²/(2a) − x⁴/(8a³) − …, so the numerator is x²(1/(2a) − 1/4) + x⁴/(8a³) + …. Finiteness forces 1/(2a) = 1/4, i.e. a = 2, and then L = 1/(8·8) = 1/64.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-limits-continuity-67", "question": "How many of the following are correct?\n(1) Every function differentiable at a point is continuous there.\n(2) f(x) = |x|³ is differentiable at x = 0.\n(3) f(x) = x^(1/3) is differentiable at x = 0.\n(4) The product of two functions, neither differentiable at a, can be differentiable at a.", "options": ["Only three", "Only one", "Only two", "All four"], "answer": 0, "explanation": "(1) true. (2) true: [|h|³ − 0]/h = h|h| → 0. (3) false: h^(1/3)/h = h^(−2/3) → ∞ (vertical tangent). (4) true: |x|·|x| = x² is differentiable at 0. So three are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-68", "question": "lim (x → π/4) (tan x)^(tan 2x) equals:", "options": ["e", "1/e", "1", "e²"], "answer": 1, "explanation": "This is 1^∞: the limit is e^L with L = lim (tan x − 1)·tan 2x = lim (tan x − 1)·2 tan x/(1 − tan²x) = lim −2 tan x/(1 + tan x) = −1. So the limit is e⁻¹.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-69", "question": "Assertion (A): f(x) = (e^(1/x) − 1)/(e^(1/x) + 1) for x ≠ 0, with f(0) = 0, is discontinuous at x = 0.\nReason (R): lim (x → 0⁺) f(x) = 1 and lim (x → 0⁻) f(x) = −1.", "options": ["Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "Both A and R are true, and R is the correct explanation of A", "A is false but R is true"], "answer": 2, "explanation": "As x → 0⁺, e^(1/x) → ∞ and f = (1 − e^(−1/x))/(1 + e^(−1/x)) → 1. As x → 0⁻, e^(1/x) → 0 and f → −1. The one-sided limits differ (a jump), which is exactly why f is discontinuous at 0.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-70", "question": "f is differentiable with f(2) = 4 and f′(2) = 1. Then lim (x → 2) [x f(2) − 2f(x)]/(x − 2) equals:", "options": ["−2", "2", "6", "4"], "answer": 1, "explanation": "Add and subtract 2f(2): [x f(2) − 2f(2) + 2f(2) − 2f(x)]/(x − 2) = f(2) − 2[f(x) − f(2)]/(x − 2) → f(2) − 2f′(2) = 4 − 2 = 2.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"math-limits-continuity-71","question":"lim (x → 0) (cos 3x − cos 5x)/x² equals:","options":["8","16","−8","4"],"answer":0,"explanation":"cos 3x − cos 5x = 2 sin 4x · sin x, so the ratio is 2·(sin 4x/x)·(sin x/x) → 2·4·1 = 8. Equivalently (5² − 3²)/2 = 8; writing (3² − 5²)/2 = −8 is the sign slip.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-72","question":"f(x) = sin(πx)/(x − 1) for x ≠ 1 is made continuous at x = 1. The value f(1) must be:","options":["π","−π","0","1/π"],"answer":1,"explanation":"Put x = 1 + h: sin(π + πh) = −sin(πh), so f → −sin(πh)/h → −π. Taking sin(πx)/(x − 1) → π forgets that sin(π + θ) = −sin θ.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-73","question":"The number of points at which f(x) = 1/(x² − 3|x| + 2) is discontinuous is:","options":["2","3","4","0"],"answer":2,"explanation":"The denominator is (|x| − 1)(|x| − 2), which vanishes at |x| = 1 and |x| = 2, i.e. x = ±1, ±2: 4 points. Solving only x² − 3x + 2 = 0 gives just 2, missing the negative roots.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-74","question":"lim (x → 1) (xˣ − x)/(ln x − x + 1) equals:","options":["2","1/2","−1","−2"],"answer":3,"explanation":"Put x = 1 + h. x ln x = h + h²/2 + …, so xˣ = 1 + h + h² + …, and xˣ − x ≈ h². ln x − x + 1 = (h − h²/2) − h = −h²/2. The limit is h²/(−h²/2) = −2; dropping the sign of the denominator gives 2.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-75","question":"lim (x → 0) [ln(1 + x + x²) + ln(1 − x + x²)]/(sec x − cos x) equals:","options":["1","2","1/2","0"],"answer":0,"explanation":"The numerator is ln[(1 + x²)² − x²] = ln(1 + x² + x⁴) ≈ x². The denominator is (1 − cos²x)/cos x = sin²x/cos x ≈ x². So the limit is 1. Using ln(1 + u) ≈ u for each log separately (forgetting −u²/2) gives 2x² and the wrong answer 2.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-76","question":"The number of points at which f(x) = (x³ − x)·|x² − 4x + 3| + sin|x| is NOT differentiable is:","options":["3","2","4","1"],"answer":1,"explanation":"|x² − 4x + 3| = |x − 1||x − 3|. At x = 1 the factor (x³ − x) also contains (x − 1), giving (x − 1)|x − 1|, which is differentiable; at x = 3 the multiplier 3³ − 3 = 24 ≠ 0, so there is a corner. sin|x| has a corner at x = 0 (one-sided slopes ±1) while the first term is smooth there. So exactly 2 points (x = 0, 3); counting x = 1 gives the trap 3.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-77","question":"With [·] the greatest integer function, lim (x → 0) [sin⁻¹x · tan⁻¹x / x²] equals:","options":["−1","1","0","does not exist"],"answer":2,"explanation":"sin⁻¹x/x = 1 + x²/6 + … and tan⁻¹x/x = 1 − x²/3 + …, so the product is 1 − x²/6 + … , slightly LESS than 1 on both sides of 0. Its greatest integer is 0, so the limit is 0. Answering 1 ignores which side of 1 the quantity approaches from.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-78","question":"g(x) = (x² − 1)·lim (n → ∞) (x²ⁿ − 1)/(x²ⁿ + 1). Then g is:","options":["discontinuous at x = ±1","differentiable everywhere","continuous everywhere but not differentiable at x = 0","continuous everywhere but not differentiable at x = ±1"],"answer":3,"explanation":"The limit is 1 for |x| > 1, −1 for |x| < 1 and 0 at |x| = 1. So g(x) = x² − 1 for |x| > 1, 1 − x² for |x| < 1 and 0 at ±1, i.e. g(x) = |x² − 1|. It is continuous (the jump of the limit is killed by the zero of x² − 1) but has corners at ±1 (slopes ∓2 and ±2).","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-79","question":"lim (x → 0) [1 − cos(1 − cos x)]/x⁴ equals:","options":["1/8","1/2","1/16","1/4"],"answer":0,"explanation":"Let u = 1 − cos x ≈ x²/2. Then 1 − cos u ≈ u²/2 = (x²/2)²/2 = x⁴/8, so the limit is 1/8. Stopping at u²/2 → x⁴/4 (squaring x² instead of x²/2) gives the trap 1/4.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "math-limits-continuity-80", "question": "With [·] the greatest integer function, the number of points in (0, π) at which f(x) = [2 sin x] is discontinuous is:", "options": ["2", "3", "1", "4"], "answer": 1, "explanation": "2 sin x rises from 0 to 2 and falls back. It crosses the integer 1 at x = π/6 and 5π/6 (jumps of [·]), and it touches 2 only at x = π/2, where f = 2 while nearby values are 1: an isolated discontinuity. Total 3; missing the touching point π/2 gives 2.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-81", "question": "lim (x → 0) [(1 + x)^(1/x) − e + ex/2]/x² equals:", "options": ["e/24", "7e/24", "11e/24", "−11e/24"], "answer": 2, "explanation": "(1/x) ln(1 + x) = 1 − x/2 + x²/3 − …, so (1 + x)^(1/x) = e·exp(−x/2 + x²/3) = e[1 − x/2 + x²/3 + x²/8 + …] = e − ex/2 + (11e/24)x² + …. Hence the limit is 11e/24; forgetting the (x/2)²/2 term from the exponential leaves e/3, and dropping x²/3 leaves e/8 — neither is the answer.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"math-limits-continuity-82","question":"lim (x → 0) [sin(tan x) − tan(sin x)]/x⁷ equals:","options":["0","1/30","−1/15","−1/30"],"answer":3,"explanation":"sin(tan x) and tan(sin x) have the same Taylor series up to x⁵ (both are x + x³/6 − x⁵/40 + …), so lower powers cancel; the first difference is at x⁷: sin(tan x) − tan(sin x) = −x⁷/30 + …. The limit is −1/30. Answering 0 assumes the cancellation goes on forever.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "math-limits-continuity-83", "question": "If lim (x → 0) [x(a + b cos x) − c sin x]/x⁵ = 1, then a + b + c equals:", "options": ["360", "240", "180", "120"], "answer": 0, "explanation": "Expand: x(a + b − bx²/2 + bx⁴/24) − c(x − x³/6 + x⁵/120). Coefficients: x: a + b − c = 0; x³: −b/2 + c/6 = 0 ⇒ c = 3b; x⁵: b/24 − c/120 = b/60 = 1 ⇒ b = 60, c = 180, a = 120. So a + b + c = 360.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"math-limits-continuity-84","question":"f(x) = |x|^α · sin(1/x) for x ≠ 0 and f(0) = 0 (α > 0). f is differentiable at 0 but f′ is NOT continuous at 0 exactly when α lies in:","options":["(0, 1]","(1, 2]","(2, ∞)","(1, ∞)"],"answer":1,"explanation":"f′(0) = lim |h|^α sin(1/h)/h exists (= 0) iff α > 1. For x > 0, f′(x) = αx^(α−1) sin(1/x) − x^(α−2) cos(1/x); the second term → 0 only if α > 2, and oscillates (or blows up) for α ≤ 2. So differentiable with discontinuous derivative ⇔ 1 < α ≤ 2. (1, ∞) is just 'differentiable'.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-limits-continuity-85","question":"lim (n → ∞) n·sin(2π√(n² + 1)) (n a natural number) equals:","options":["2π","0","π","π/2"],"answer":2,"explanation":"√(n² + 1) = n + 1/(2n) − …, so 2π√(n² + 1) = 2πn + π/n − …, and sin(2πn + π/n) = sin(π/n). Then n sin(π/n) → π. Answering 0 (from |sin| ≤ 1 thinking) misses that the angle approaches a multiple of 2π.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "math-limits-continuity-86", "question": "f(x) = lim (n → ∞) [ax + x²ⁿ(x² + b)]/(1 + x²ⁿ) is continuous on R for exactly one pair (a, b). For that pair, the number of points where f is not differentiable is:", "options": ["0", "1", "3", "2"], "answer": 3, "explanation": "f = ax for |x| < 1, x² + b for |x| > 1, f(1) = (a + 1 + b)/2, f(−1) = (−a + 1 + b)/2. Continuity at 1 needs a = 1 + b, at −1 needs −a = 1 + b, so a = 0, b = −1: f = 0 inside, x² − 1 outside. At x = ±1 the one-sided slopes are 0 and ±2, so f is non-differentiable at 2 points.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"math-limits-continuity-87","question":"If lim (x → ∞) [∛(x³ + 6x² + 1) − √(x² + ax + 3)] = 1, then a equals:","options":["4","−2","6","2"],"answer":3,"explanation":"∛(x³ + 6x² + 1) = x(1 + 6/x + …)^(1/3) = x + 2 + o(1) and √(x² + ax + 3) = x + a/2 + o(1). The limit is 2 − a/2 = 1, so a = 2. a = 4 is what makes the limit 0.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "math-limits-continuity-88", "question": "With [·] the greatest integer function, the number of points in the open interval (0, 3) at which f(x) = [x² − 2x] is discontinuous is:", "options": ["3", "4", "2", "5"], "answer": 0, "explanation": "x² − 2x = (x − 1)² − 1 takes values in [−1, 3) on (0, 3). It equals −1 only at its minimum x = 1, where nearby values lie in (−1, 0): [·] = −1 on both sides, so f is continuous there. It crosses 0, 1, 2 at x = 2, 1 + √2, 1 + √3 — 3 discontinuities. Counting the minimum x = 1 gives the trap 4.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-89", "question": "How many of the following statements are correct?\n(1) lim (x → 0) sin(1/x) does not exist.\n(2) If lim (x → a) f(x)g(x) exists, then lim f(x) and lim g(x) both exist.\n(3) If f is continuous on R and f(x) is rational for every x, then f is constant.\n(4) If |f| is continuous at a, then f is continuous at a.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "(1) true: sin(1/x) oscillates between −1 and 1. (2) false: f = x and g = sin(1/x) near 0 give a product → 0. (3) true: a non-constant continuous f takes every value between two of its values (IVT), including irrationals. (4) false: f = 1 for x ≥ 0, −1 for x < 0 has |f| = 1. Two are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"math-limits-continuity-90","question":"With [·] the greatest integer function, f(x) = [x] + √(x − [x]) is:","options":["discontinuous at every integer","continuous everywhere but not differentiable at any integer","differentiable everywhere","continuous only at non-integers"],"answer":1,"explanation":"At an integer m: left limit (m − 1) + √1 = m, right limit m + 0 = m, f(m) = m, so f is continuous. But the right-hand derivative is lim √h/h = ∞, so f is not differentiable at integers (elsewhere it is m + √(x − m), smooth). The jump of [x] is exactly cancelled by √{x} — the trap is to call it discontinuous.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "math-limits-continuity-91", "question": "lim (x → 0) [(1 + x)^(1/x)/e]^(1/x) equals:", "options": ["e^(1/2)", "1", "e^(−1/2)", "1/e"], "answer": 2, "explanation": "ln of the expression = (1/x)[(1/x) ln(1 + x) − 1] = (1/x)[1 − x/2 + x²/3 − … − 1] = −1/2 + x/3 − … → −1/2. So the limit is e^(−1/2). Treating it as 1^∞ = 1 without computing the exponent is the trap.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-92", "question": "lim (x → 0) (1/x² − cot²x) equals:", "options": ["1/3", "0", "−2/3", "2/3"], "answer": 3, "explanation": "1/x² − cot²x = (tan²x − x²)/(x² tan²x). tan x = x + x³/3 + …, so tan²x − x² = 2x⁴/3 + … and x² tan²x ≈ x⁴. The limit is 2/3. Using cot x ≈ 1/x − x/3 gives cot²x ≈ 1/x² − 2/3, the same 2/3; dropping the factor 2 gives the trap 1/3.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-limits-continuity-93", "question": "lim (n → ∞) cos(x/2)·cos(x/4)·cos(x/8)⋯cos(x/2ⁿ), evaluated at x = π/2, equals:", "options": ["2/π", "1", "0", "π/2"], "answer": 0, "explanation": "Multiply by sin(x/2ⁿ) and use 2 sin θ cos θ = sin 2θ repeatedly: the product equals sin x/(2ⁿ sin(x/2ⁿ)) → sin x/x. At x = π/2 this is 1/(π/2) = 2/π. Answering 0 (an infinite product of numbers below 1) ignores that the factors tend to 1 fast enough.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-limits-continuity-94", "question": "f(x) = x² when x is rational and f(x) = 2x − 1 when x is irrational. Which statement is correct?", "options": ["f is continuous only at x = 1 but not differentiable there", "f is continuous only at x = 1 and is differentiable there", "f is continuous at x = 0 and x = 1 only", "f is continuous nowhere"], "answer": 1, "explanation": "Continuity needs both rules to give the same limit: x² = 2x − 1 ⇔ (x − 1)² = 0 ⇔ x = 1. At x = 1, [f(1 + h) − f(1)]/h equals (2h + h²)/h = 2 + h (rational) or 2h/h = 2 (irrational); both → 2, so f′(1) = 2 exists. The line 2x − 1 is the tangent to x² at 1, which is why the derivative exists.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"math-limits-continuity-95","question":"With [·] the greatest integer function, lim (n → ∞) ([√2] + [2√2] + [3√2] + … + [n√2])/n² equals:","options":["√2","1/2","1/√2","0"],"answer":2,"explanation":"k√2 − 1 < [k√2] ≤ k√2, so the sum lies between √2·n(n + 1)/2 − n and √2·n(n + 1)/2. Dividing by n² and letting n → ∞ (sandwich theorem), both bounds → √2/2 = 1/√2. Answering √2 forgets the 1/2 from Σk = n(n + 1)/2.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-limits-continuity-96","question":"lim (x → 0) (√(1 + x) − 1)/x equals:","options":["1/2","1","0","2"],"answer":0,"explanation":"Rationalise: (√(1 + x) − 1)/x = 1/(√(1 + x) + 1), which tends to 1/2 as x → 0.","difficulty":"easy","source":"JEE Main"},
  {"id":"math-limits-continuity-97","question":"lim (x → ∞) (2x + 3)/√(4x² + 1) equals:","options":["2","1/2","1","∞"],"answer":2,"explanation":"For x > 0, √(4x² + 1) = x√(4 + 1/x²). Dividing numerator and denominator by x gives (2 + 3/x)/√(4 + 1/x²) → 2/2 = 1.","difficulty":"easy","source":"JEE Main"},
  {"id":"math-limits-continuity-98","question":"lim (x → 0) (1 − cos 4x)/(x sin 3x) equals:","options":["4/3","16/3","2/3","8/3"],"answer":3,"explanation":"1 − cos 4x = 2 sin²2x ≈ 8x², and x sin 3x ≈ 3x². The limit is 8/3.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-limits-continuity-99","question":"lim (x → 1) (√x − 1)/(∛x − 1) equals:","options":["2/3","1","3/2","6"],"answer":2,"explanation":"Put x = t⁶, so t → 1: (t³ − 1)/(t² − 1) = (t² + t + 1)/(t + 1) → 3/2. (Equivalently, the ratio of the derivatives 1/2 and 1/3 at x = 1.)","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-limits-continuity-100","question":"lim (x → ∞) (1 − 3/x)^(2x) equals:","options":["e⁶","e⁻⁶","e⁻³ᐟ²","1"],"answer":1,"explanation":"This is a 1^∞ form: the limit is e^L with L = lim 2x × (−3/x) = −6. So the answer is e⁻⁶.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-limits-continuity-101","question":"f(x) = (1 − cos kx)/(x sin x) for x ≠ 0 and f(0) = 1/2. f is continuous at x = 0 exactly when k equals:","options":["±1","±2","±1/2","1 only"],"answer":0,"explanation":"As x → 0, 1 − cos kx ≈ k²x²/2 and x sin x ≈ x², so f(x) → k²/2. Continuity needs k²/2 = 1/2, i.e. k = ±1 (cos is even, so the sign of k does not matter).","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-limits-continuity-102","question":"With [·] the greatest integer function, the number of points in (−2, 2) at which f(x) = 1/(x² − 1) + [x] is discontinuous is:","options":["3","2","4","5"],"answer":0,"explanation":"1/(x² − 1) is discontinuous at x = ±1, and [x] jumps at the integers −1, 0, 1 in (−2, 2). The union is {−1, 0, 1}: 3 points (the two parts cannot cancel at ±1 since 1/(x² − 1) is unbounded there).","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-limits-continuity-103","question":"lim (x → 0) (eˣ − e^(sin x))/(x − sin x) equals:","options":["0","1","e","1/6"],"answer":1,"explanation":"Factor out e^(sin x): the expression is e^(sin x) × (e^(x − sin x) − 1)/(x − sin x). With t = x − sin x → 0, (eᵗ − 1)/t → 1, and e^(sin x) → 1. So the limit is 1, with no series expansion needed.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-limits-continuity-104","question":"lim (x → ∞) x(x^(1/x) − 1)/ln x equals:","options":["0","e","1","∞"],"answer":2,"explanation":"x^(1/x) − 1 = e^(ln x/x) − 1, and ln x/x → 0, so e^(ln x/x) − 1 ≈ ln x/x. Hence x(x^(1/x) − 1)/ln x → 1.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-limits-continuity-105","question":"lim (n → ∞) Σ (k = 1 to n) n/(n² + k²) equals:","options":["π/2","ln 2","1","π/4"],"answer":3,"explanation":"Write the term as (1/n) × 1/(1 + (k/n)²). The sum is a Riemann sum for ∫₀¹ dx/(1 + x²) = tan⁻¹1 = π/4.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-limits-continuity-106","question":"lim (x → 0⁺) (sin x)^(tan x) equals:","options":["0","e","1","the limit does not exist"],"answer":2,"explanation":"This is a 0⁰ form. ln of the expression is tan x · ln sin x ≈ x ln x → 0 as x → 0⁺. So the limit is e⁰ = 1.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-limits-continuity-107","question":"lim (x → 0) (cos x + sin x)^(1/x) equals:","options":["e","1","e²","√e"],"answer":0,"explanation":"1^∞ form: the limit is e^L with L = lim (cos x + sin x − 1)/x = lim [(cos x − 1)/x + sin x/x] = 0 + 1 = 1. So the answer is e.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-limits-continuity-108","question":"The number of points at which f(x) = |x − 1|(x − 1) + |x − 2| is not differentiable is:","options":["2","0","3","1"],"answer":3,"explanation":"|x − 1|(x − 1) equals (x − 1)² for x ≥ 1 and −(x − 1)² for x < 1; both one-sided derivatives at 1 are 0, so it is differentiable there. Only |x − 2| has a corner, at x = 2. So there is exactly one such point.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-limits-continuity-109","question":"With [·] the greatest integer function, the function f(x) = [x]·sin(πx) on R is:","options":["discontinuous at every integer","continuous everywhere but not differentiable at any integer","differentiable everywhere","continuous everywhere and not differentiable only at x = 0"],"answer":1,"explanation":"At an integer n, sin(πx) → 0 from both sides, so the jump of [x] is killed: f is continuous everywhere. The left derivative at n is (n − 1)π cos nπ and the right derivative is nπ cos nπ; these always differ by π, so f is not differentiable at any integer.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-limits-continuity-110","question":"lim (x → 0) (2ˣ − 1 − x ln 2)/x² equals:","options":["(ln 2)²","(ln 2)²/2","ln 2/2","0"],"answer":1,"explanation":"2ˣ = e^(x ln 2) = 1 + x ln 2 + (x ln 2)²/2 + …. Subtracting 1 + x ln 2 and dividing by x² leaves (ln 2)²/2.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-limits-continuity-111","question":"lim (x → ∞) [√(x² + x + 1) − √(x² − x + 1)] equals:","options":["0","2","1/2","1"],"answer":3,"explanation":"Rationalise: the difference is 2x/[√(x² + x + 1) + √(x² − x + 1)]. Dividing by x, this tends to 2/(1 + 1) = 1.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-limits-continuity-112","question":"lim (x → 0) x(2ˣ − 1)/(1 − cos x) equals:","options":["2 ln 2","ln 2","(ln 2)/2","0"],"answer":0,"explanation":"Use 2ˣ − 1 ≈ x ln 2 and 1 − cos x ≈ x²/2. The expression behaves like x·x ln 2/(x²/2) = 2 ln 2.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-limits-continuity-113","question":"lim (x → 0) [1 + sin x − cos x + ln(1 − x)]/(x tan²x) equals:","options":["1/2","−1/6","−1/2","0"],"answer":2,"explanation":"Expand: sin x = x − x³/6, cos x = 1 − x²/2, ln(1 − x) = −x − x²/2 − x³/3. The numerator becomes x − x³/6 + x²/2 − x − x²/2 − x³/3 = −x³/2 + …, while x tan²x ≈ x³. The limit is −1/2.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-limits-continuity-114","question":"The number of points at which f(x) = max(|x|, x²) is not differentiable is:","options":["2","1","5","3"],"answer":3,"explanation":"|x| ≥ x² exactly when |x| ≤ 1, so f(x) = |x| on [−1, 1] and x² outside. There are corners at x = 0 (slopes −1, 1) and at x = ±1 (slopes ±1 meet ±2). So f fails to be differentiable at 3 points.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-limits-continuity-115","question":"lim (x → 0) [sin(sin x) − sin x]/x³ equals:","options":["1/6","−1/3","−1/6","0"],"answer":2,"explanation":"Let u = sin x. Then sin u − u ≈ −u³/6, and u³ ≈ x³. So the limit is −1/6.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-limits-continuity-116","question":"lim (n → ∞) n[e − (1 + 1/n)ⁿ] equals:","options":["e","e/2","1/2","0"],"answer":1,"explanation":"n ln(1 + 1/n) = 1 − 1/(2n) + O(1/n²), so (1 + 1/n)ⁿ = e·e^(−1/(2n) + …) = e − e/(2n) + O(1/n²). Hence n[e − (1 + 1/n)ⁿ] → e/2.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-limits-continuity-117","question":"lim (n → ∞) Σ (k = 1 to n) 1/√(n² + kn) equals:","options":["2(√2 − 1)","√2 − 1","2√2","1"],"answer":0,"explanation":"1/√(n² + kn) = (1/n) × 1/√(1 + k/n). The sum is a Riemann sum for ∫₀¹ dx/√(1 + x) = [2√(1 + x)]₀¹ = 2√2 − 2.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-limits-continuity-118","question":"lim (x → 0) (1/x)(cot x − 1/x) equals:","options":["−1/3","1/3","0","−1/6"],"answer":0,"explanation":"cot x = 1/x − x/3 − x³/45 − …, so cot x − 1/x ≈ −x/3. Dividing by x gives −1/3.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-limits-continuity-119","question":"For natural numbers n, lim (n → ∞) sin²(π√(n² + n)) equals:","options":["0","1","1/2","the limit does not exist"],"answer":1,"explanation":"√(n² + n) = n√(1 + 1/n) = n + 1/2 − 1/(8n) + …. So π√(n² + n) = nπ + π/2 − ε with ε → 0, and sin² of it equals cos²ε → 1 (the integer multiple nπ does not affect sin²).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-limits-continuity-120","question":"The function f(x) = |x|³ at x = 0 is:","options":["differentiable but not twice","three times differentiable but not four times","twice differentiable but not three times","infinitely differentiable"],"answer":2,"explanation":"f′(x) = 3x|x| (continuous, f′(0) = 0) and f″(x) = 6|x|, which exists at 0 with value 0. But f‴ would be the derivative of 6|x| at 0, which does not exist (one-sided values −6 and 6).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-limits-continuity-121","question":"f is differentiable on R, f(x + y) = f(x) + f(y) + xy(x + y) for all real x, y, and f′(0) = 1. Then f′(3) equals:","options":["9","28","4","10"],"answer":3,"explanation":"f′(x) = lim [f(x + h) − f(x)]/h = lim [f(h) + xh(x + h)]/h = f′(0) + x² (note f(0) = 0 from x = y = 0). So f′(x) = 1 + x² and f′(3) = 10; indeed f(x) = x + x³/3.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-limits-continuity-122","question":"lim (x → 0) [(1 + x)ˣ − 1]/x² equals:","options":["1/2","0","1","e"],"answer":2,"explanation":"(1 + x)ˣ = e^(x ln(1 + x)) and x ln(1 + x) = x² − x³/2 + …. So (1 + x)ˣ − 1 ≈ x², and the limit is 1.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-limits-continuity-123","question":"lim (x → 0⁺) x^(xˣ) equals:","options":["0","1","e","the limit does not exist"],"answer":0,"explanation":"First xˣ = e^(x ln x) → e⁰ = 1. Then x^(xˣ) = e^(xˣ ln x), and xˣ ln x → 1 × (−∞) = −∞. So the limit is 0, not 1 (unlike xˣ itself).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-limits-continuity-124","question":"lim (x → 0) [tan(tan x) − sin(sin x)]/(tan x − sin x) equals:","options":["1","3","1/2","2"],"answer":3,"explanation":"tan(tan x) = x + 2x³/3 + … (since tan u = u + u³/3 and u = x + x³/3), and sin(sin x) = x − x³/3 + …. The numerator is x³ + …, while tan x − sin x = x³/2 + …. The limit is 2.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-limits-continuity-125","question":"lim (x → 0) [1/x − 1/(eˣ − 1)] equals:","options":["1","1/2","−1/2","0"],"answer":1,"explanation":"Combine: (eˣ − 1 − x)/[x(eˣ − 1)]. The numerator ≈ x²/2 and the denominator ≈ x². So the limit is 1/2.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-limits-continuity-126","question":"Let sgn denote the signum function and g(x) = x(1 − x²). The number of points at which sgn(g(x)) is discontinuous is:","options":["1","3","2","0"],"answer":1,"explanation":"sgn is continuous wherever its argument is non-zero, so discontinuities can occur only at the zeros −1, 0, 1 of g. g changes sign at each of these simple zeros, so sgn(g) jumps there: 3 points.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-limits-continuity-127","question":"lim (x → ∞) [sin √(x + 1) − sin √x] equals:","options":["the limit does not exist","1","1/2","0"],"answer":3,"explanation":"sin A − sin B = 2 cos((A + B)/2) sin((A − B)/2). Here A − B = √(x + 1) − √x = 1/(√(x + 1) + √x) → 0, so the sine factor → 0 while the cosine factor stays bounded. The limit is 0, even though sin √x alone oscillates.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-limits-continuity-128","question":"lim (n → ∞) Π (k = 2 to n) (k³ − 1)/(k³ + 1) equals:","options":["2/3","1/2","1","3/4"],"answer":0,"explanation":"(k³ − 1)/(k³ + 1) = [(k − 1)/(k + 1)] × [(k² + k + 1)/(k² − k + 1)]. The first factors telescope to 2/(n(n + 1)); in the second, k² − k + 1 = (k − 1)² + (k − 1) + 1, so they telescope to (n² + n + 1)/3. The product → 2/3.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-limits-continuity-129","question":"lim (x → ∞) x(π/2 − tan⁻¹x) equals:","options":["0","π/2","1","∞"],"answer":2,"explanation":"For x > 0, π/2 − tan⁻¹x = tan⁻¹(1/x). With t = 1/x → 0⁺, the expression is tan⁻¹t/t → 1.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
];

export default questions;
